import { memo, useEffect } from "react";
import { useGLTF } from "@react-three/drei";
// #if DEBUG
import { useControls } from "leva";
// #endif
import { useScene } from "@/lib/contexts/SceneContext";
import Monitor from "@/components/three/Monitor";
import Obstacle from "@/components/three/Obstacle";
import { enableShadows } from "@/utils/three";

type DeskControls = {
    deskX: number;
    deskY: number;
    deskZ: number;
    deskScale: number;
};

// Generated by .bin/generate-scene-models.mts with its back-left corner at the
// origin and its top 1 unit high, so `desk.scale` is the desk top height
const DESK_MODEL_PATH = "/models/cartoon_desk.glb";

const Desk = memo(() => {
    const { desk } = useScene();
    const deskModel = useGLTF(DESK_MODEL_PATH);

    useEffect(() => {
        enableShadows(deskModel.scene);
    }, [deskModel.scene]);

    let deskX: number, deskY: number, deskZ: number, deskScale: number;

    // #if DEBUG
    ({ deskX, deskY, deskZ, deskScale } = useControls(
        "Desk",
        {
            deskX: {
                value: desk?.position?.x ?? 0,
                min: -20,
                max: 10,
                step: 0.01,
            },
            deskY: {
                value: desk?.position?.y ?? 0,
                min: -10,
                max: 10,
                step: 0.01,
            },
            deskZ: {
                value: desk?.position?.z ?? 0,
                min: -20,
                max: 10,
                step: 0.01,
            },
            deskScale: {
                value: desk?.scale ?? 0,
                min: 0.5,
                max: 5,
                step: 0.01,
            },
        },
        { collapsed: true }
    ) as DeskControls);
    // #endif

    // #if !DEBUG
    deskX = desk?.position?.x ?? 0;
    deskY = desk?.position?.y ?? 0;
    deskZ = desk?.position?.z ?? 0;
    deskScale = desk?.scale ?? 0;
    // #endif

    // The footprint is sized for the default scale, so it grows with Leva's
    const footprintScale = deskScale / (desk?.scale || 1);
    const width = (desk?.footprint?.width ?? 0) * footprintScale;
    const depth = (desk?.footprint?.depth ?? 0) * footprintScale;
    const backArmDepth = (desk?.footprint?.backArmDepth ?? 0) * footprintScale;
    const sideArmWidth = (desk?.footprint?.sideArmWidth ?? 0) * footprintScale;

    return (
        <group position={[deskX, deskY, deskZ]}>
            {/* Desk model */}
            <primitive
                object={deskModel.scene}
                scale={[deskScale, deskScale, deskScale]}
            />

            {/* One solid box per arm of the L, from the back-left corner */}
            <Obstacle
                size={[width, deskScale, backArmDepth]}
                position={[width / 2, deskScale / 2, backArmDepth / 2]}
            />
            <Obstacle
                size={[sideArmWidth, deskScale, depth]}
                position={[sideArmWidth / 2, deskScale / 2, depth / 2]}
            />

            {/* Monitor model */}
            <Monitor />
        </group>
    );
});
Desk.displayName = "Desk";

useGLTF.preload(DESK_MODEL_PATH);

export default Desk;
